import { apiFetch } from "./apiFetch";

export type LessorClassification =
  | "operating"
  | "finance";

export type LessorBillingFrequency =
  | "weekly"
  | "monthly"
  | "quarterly"
  | "annually";

export type LessorBillingTiming =
  | "arrears"
  | "advance";

// ============================================================
// Deposit-metadata enums
//
// These six fields drive the patched preview_security_deposit_terms
// in lessor_lease_engine.py, which resolves the deposit's legal
// nature into one of three treatment_branch values:
//
//   1. tenant_beneficial_statutory       (e.g. SA residential, RHA s4B)
//   2. contractual_interest_bearing
//   3. interest_free_refundable          (IFRS 9 fair-value)
// ============================================================

export type LessorAssetType =
  | "residential"
  | "commercial"
  | "movable";

export type LessorDepositRefundability =
  | "refundable"
  | "non_refundable"
  | "partial";

export type LessorDepositInterestRequirement =
  | "statutory"
  | "contractual"
  | "none";

export type LessorDepositInterestBeneficiary =
  | "lessee"
  | "lessor";

export type LessorLeasePayload = {
  contract_no?: string | null;
  contract_name: string;
  customer_id: number | null;
  asset_id?: number | null;

  // Additional wizard and direct-cost metadata
  lessor_id?: number | null;
  lease_name?: string | null;
  cost_of_sales_account_code?: string | null;

  start_date: string;
  end_date?: string | null;
  lease_term_months?: number;

  underlying_asset_description?: string | null;
  underlying_asset_account_code?: string | null;

  underlying_asset_carrying_amount?: number;
  underlying_asset_fair_value?: number;
  economic_life_months?: number;

  guaranteed_residual_value?: number;
  unguaranteed_residual_value?: number;
  initial_direct_costs?: number;

  interest_rate_implicit?: number;

  ownership_transfers?: boolean;
  purchase_option_reasonably_certain?: boolean;
  specialised_asset?: boolean;

  classification_override?: boolean;
  classification_override_reason?: string | null;

  manufacturer_dealer_lessor?: boolean;

  billing_amount: number | null;
  billing_basis: "gross" | "net";
  vat_rate: number;

  billing_frequency: LessorBillingFrequency;
  billing_timing: LessorBillingTiming;
  bill_day_of_month?: number | null;

  lease_classification: LessorClassification;
  payment_terms_days: number;
  currency?: string | null;

  security_deposit_amount: number;
  security_deposit_discount_rate?: number;
  security_deposit_account_code?: string | null;

  security_deposit_arrangement:
    | ""
    | "fully_refundable"
    | "rent_offset"
    | "refundable_less_deductions"
    | "non_refundable";

  security_deposit_interest_bearing: boolean;
  security_deposit_separate_account: boolean;
  security_deposit_discount_deferred: boolean;
  security_deposit_received?: boolean;

  // ----------------------------------------------------------
  // Six deposit-metadata fields consumed by the patched
  // preview_security_deposit_terms to resolve the deposit's
  // legal nature and choose a treatment_branch.
  // ----------------------------------------------------------
  asset_type?: LessorAssetType | "";
  jurisdiction?: string;
  deposit_refundability?: LessorDepositRefundability | "";
  deposit_interest_requirement?:
    | LessorDepositInterestRequirement
    | "";
  deposit_interest_beneficiary?:
    | LessorDepositInterestBeneficiary
    | "";
  deposit_permitted_deductions?: string;

  revenue_account_code?: string | null;
  vat_output_account_code?: string | null;
  ar_account_code?: string | null;
  bank_account_code?: string | null;
  bank_account_id?: number | null;

  finance_income_account_code?: string | null;

  net_investment_current_account_code?:
    string | null;

  net_investment_noncurrent_account_code?:
    string | null;

  notes?: string | null;
};

// Finance lease rentals are calculated by the backend.
// Never send a previously calculated rental back as
// though it were a manually supplied contractual rental.
function normalizeLessorLeasePayload(
  payload: LessorLeasePayload
): LessorLeasePayload {
  return {
    ...payload,
    billing_amount:
      payload.lease_classification === "finance"
        ? 0
        : payload.billing_amount,
  };
}

