  function validateStep1() {
    if (!form.asset_id) {
      return "Select the underlying asset.";
    }

    if (
      Number(
        form.underlying_asset_carrying_amount || 0
      ) < 0
    ) {
      return "Asset carrying amount cannot be negative.";
    }

    if (
      Number(
        form.underlying_asset_fair_value || 0
      ) <= 0
    ) {
      return "Underlying asset fair value must be greater than zero.";
    }

    if (
      Number(form.lease_term_months || 0) <= 0
    ) {
      return "Lease term must be greater than zero.";
    }

    if (
      Number(form.economic_life_months || 0) <= 0
    ) {
      return "Economic life must be greater than zero.";
    }

    if (
      Number(form.interest_rate_implicit || 0) < 0
    ) {
      return "Implicit interest rate cannot be negative.";
    }

    if (
      form.classification_override &&
      !String(
        form.classification_override_reason || ""
      ).trim()
    ) {
      return "Enter a reason for the classification override.";
    }

    return null;
  }

  function validateStep2() {
    if (!form.contract_name.trim()) {
      return "Contract name is required.";
    }

    if (!form.customer_id) {
      return "Select the customer or lessee.";
    }

    if (!form.start_date) {
      return "Start date is required.";
    }

    if (!form.end_date) {
      return "End date is required.";
    }

    if (form.end_date < form.start_date) {
      return "End date cannot be before start date.";
    }

    if (termMonths <= 0) {
      return "Lease term must be greater than zero.";
    }

    if (
      Number(form.lease_term_months || 0) &&
      termMonths !==
        Number(form.lease_term_months)
    ) {
      return (
        "The agreement dates produce a " +
        `${termMonths}-month term, but Step 1 ` +
        `was classified using ` +
        `${form.lease_term_months} months. ` +
        "Return to Step 1 and update the expected lease term."
      );
    }

    if (
      Number(form.security_deposit_amount || 0) < 0
    ) {
      return "Security deposit cannot be negative.";
    }

    if (
      Number(form.security_deposit_amount || 0) > 0 &&
      !form.security_deposit_arrangement
    ) {
      return "Select the contractual security deposit arrangement.";
    }

    // -----------------------------------------------------
    // Deposit-metadata validation -- the patched engine
    // resolves the treatment_branch from these fields.
    // -----------------------------------------------------
    if (Number(form.security_deposit_amount || 0) > 0) {
      const assetType = String(
        form.asset_type || ""
      ).trim();
      if (!assetType) {
        return "Select the underlying asset type so the deposit's legal nature can be resolved.";
      }

      const jurisdiction = String(
        form.jurisdiction || ""
      ).trim();
      if (!jurisdiction) {
        return "Select the jurisdiction that governs the deposit.";
      }

      const refundability = String(
        form.deposit_refundability || ""
      ).trim();
      if (!refundability) {
        return "Select whether the deposit is refundable, non-refundable, or partially refundable.";
      }

      const interestRequirement = String(
        form.deposit_interest_requirement || ""
      ).trim();
      if (!interestRequirement) {
        return "Select whether interest on the deposit is statutory, contractual, or none.";
      }

      const interestBeneficiary = String(
        form.deposit_interest_beneficiary || ""
      ).trim();
      if (!interestBeneficiary) {
        return "Select whether the deposit interest belongs to the lessee or the lessor.";
      }

      // South African residential property deposits are
      // governed by the Rental Housing Act 50 of 1999 s4B:
      // statutory interest, payable to the tenant. Refuse
      // any combination that contradicts that rule rather
      // than silently posting a discount gain.
      const isSaResidential =
        jurisdiction.toLowerCase() === "south africa" &&
        assetType.toLowerCase() === "residential";

      if (
        isSaResidential &&
        interestRequirement.toLowerCase() !== "statutory"
      ) {
        return "South African residential deposits must be treated as statutory interest-bearing under the Rental Housing Act 50 of 1999 s4B.";
      }

      if (
        isSaResidential &&
        interestBeneficiary.toLowerCase() !== "lessee"
      ) {
        return "Interest on a South African residential deposit belongs to the tenant under the Rental Housing Act 50 of 1999 s4B.";
      }
    }

    if (
      form.security_deposit_discount_deferred &&
      form.security_deposit_interest_bearing
    ) {
      return "An interest-bearing deposit cannot be treated as an interest-free deferred deposit.";
    }

    if (
      form.security_deposit_discount_deferred &&
      ![
        "fully_refundable",
        "refundable_less_deductions",
      ].includes(form.security_deposit_arrangement)
    ) {
      return "Discounting is only available for refundable, interest-free deposits.";
    }

    if (
      form.security_deposit_discount_deferred &&
      Number(form.security_deposit_discount_rate || 0) <= 0
    ) {
      return "Enter a positive annual discount rate for the deferred refundable deposit.";
    }

    return null;
  }

